import sys; sys.path.insert(0, '.')
import numpy as np
import gate

def ln_eps_outside(x):
    wide = np.asarray(x, dtype=np.float64)
    c = wide - wide.mean(-1, keepdims=True)
    v = (c*c).mean(-1, keepdims=True)
    return (c / (np.sqrt(v) + 1e-5)).astype(x.dtype)

def ln_no_eps(x):
    wide = np.asarray(x, dtype=np.float64)
    c = wide - wide.mean(-1, keepdims=True)
    v = (c*c).mean(-1, keepdims=True)
    with np.errstate(all="ignore"):
        y = np.where(v > 0, c / np.sqrt(v), 0.0)
    return y.astype(x.dtype)

def ln_eps_1e3(x):
    wide = np.asarray(x, dtype=np.float64)
    c = wide - wide.mean(-1, keepdims=True)
    v = (c*c).mean(-1, keepdims=True)
    return (c / np.sqrt(v + 1e-3)).astype(x.dtype)

def scale_drift(x):
    ref = gate.reference()(x).astype(np.float64)
    n = x.shape[-1]
    return (ref * (1 + 5 * np.finfo(np.float32).eps * n)).astype(x.dtype)

for name, k in [("eps_outside", ln_eps_outside), ("no_eps", ln_no_eps), ("eps_1e-3", ln_eps_1e3), ("scale_drift", scale_drift)]:
    r = gate.check(k, include_laws=False)
    print(name, {a: (f, t) for a, (f, t, _) in r.items()})
    for a, (f, t, first) in r.items():
        if first: print("    ", a, first)
